// Прод, только чтение: сырой HTML через request API с двумя User-Agent.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, rootHtml, seoBody, categoryPath, UA_DESKTOP, UA_GOOGLEBOT } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('SSR-блок одинаков для обычного браузера и Googlebot: главная, поиск, категория, объявление #b3dc2e @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.categories.length, 'категории в sitemap').toBeGreaterThan(0);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);
    const urls = ['/', '/search', categoryPath(sm.categories[0]), `/businessdetail?id=${sm.listingIds[0]}`];

    for (const url of urls) {
      await test.step(url, async () => {
        const human = await rawHtml(request, url, UA_DESKTOP);
        const bot = await rawHtml(request, url, UA_GOOGLEBOT);
        expect(human.status, `${url} обычный UA`).toBe(200);
        expect(bot.status, `${url} Googlebot`).toBe(200);
        const a = seoBody(rootHtml(human.html) ?? '');
        const b = seoBody(rootHtml(bot.html) ?? '');
        expect(a, `${url}: SSR-блок для обычного UA`).toBeTruthy();
        expect(b?.html, `${url}: SSR-блок Googlebot = обычного UA`).toBe(a!.html);
      });
    }
  });
});
